'use strict';
// Home Screen design study. Native WidgetKit/AppWidget integration is deferred.
const widgetPreview={mode:'next'};
function widgetNearestEvent(events,mode){if(mode==='quiet')return null;if(mode==='several'||mode==='stale')mode='next';return [...events].filter(r=>r.renewal&&(mode==='next'||(mode==='trial'?r.trial:!r.trial))).sort((a,b)=>a.renewal.localeCompare(b.renewal)||String(a.id).localeCompare(String(b.id)))[0]||null;}
function widgetEventCopy(record,today){if(!record)return {title:'A little peace of mind.',timing:'Nothing coming up',amount:'All clear',type:'quiet'};const days=Math.round((Date.parse(record.renewal+'T00:00:00Z')-Date.parse(today+'T00:00:00Z'))/86400000),verb=record.trial?'Trial ends':'Renews';return {title:record.name,timing:verb+(days===0?' today':days===1?' tomorrow':' in '+days+' days'),when:days===0?'Today':days===1?'Tomorrow':'In '+days+' days',amount:record.expectedCharge===false?'Auto-renew off':Number.isFinite(Number(record.price))&&record.price!==null&&record.price!==''?uiMoney(record.currency,Number(record.price).toFixed(2)).replace('\uE900','SAR').replace('\uE901','AED'):'Amount not set',type:record.trial?'trial':days===0?'today':'renewal'};}
function widgetDoorScene(){return `<div class="wk-knock-scene" aria-hidden="true"><div class="wk-knock-avatar">${mascotView({expression:'happy',size:92,artworkScale:1.4,halo:false})}<svg class="wk-fist" viewBox="0 0 42 34"><path d="M8 24 7 13q0-5 4-5 3 0 4 4V6q0-4 4-4t4 4v5-4q0-4 4-4t4 4v5q1-4 4-3t3 5v8q0 8-11 9H16q-6-1-8-7Z"/><path d="M15 12v8m8-9v8m8-7v7"/></svg></div><div class="wk-door-frame"><div class="wk-door"><i></i><b></b></div></div><span class="wk-knock-lines"><i></i><i></i><i></i></span><span class="wk-knock-words">knock, knock.</span></div>`;}
function widgetTile(record,size,opts={}){const stale=!!opts.stale,more=record&&!stale?opts.more||0:0,copy=widgetEventCopy(stale?null:record,calendarToday),quiet=!record||stale;return `<button class="wk-tile wk-${size} wk-type-${copy.type} ${quiet?'wk-quiet':''}" data-widget-open="${record&&!stale?escape(record.id):''}" aria-label="${stale?'Time to check in. Open Renewless to see what’s next.':record?escape(copy.title+'. '+copy.timing+', '+detailDate(record.renewal)+(record.estimated?', estimated date':'')+'. '+copy.amount+(record.trial&&record.expectedCharge!==false?' after trial':'')+(more?'. And '+more+' more on this day':'')+'. Open subscription'):'Open Renewless'}"><span class="wk-brand"><img src="assets/renewless-mark.svg" alt=""><span>RENEWLESS</span><span class="wk-event-dot"></span></span><span class="wk-final-content">${quiet?`<span class="wk-quiet-art">${mascotView({expression:stale?'neutral':'happy',size:64,artworkScale:1.05,halo:false})}</span><strong class="wk-service">${stale?'Time to check in.':'All clear.'}</strong><span class="wk-timing">${stale?'Open Renewless':'Nothing coming up.'}</span><span class="wk-date-label">${stale?'to see what’s next.':'A little peace of mind.'}</span>`:`<span class="wk-eyebrow-row"><span class="wk-event-eyebrow">${record.trial?'TRIAL ENDING':copy.type==='today'?'DUE TODAY':'NEXT RENEWAL'}</span>${more?`<span class="wk-more">+${more}</span>`:''}</span><span class="wk-service"><span class="wk-platform-logo">${platformLogo(record.name)}</span>${escape(record.name)}</span><strong class="wk-amount ${copy.amount.length>12?'wk-amount-compact':''}">${escape(copy.amount)}</strong><span class="wk-timing">${escape(copy.when)} · ${detailDate(record.renewal).replace(/ \d{4}$/,'')}</span>`}</span>${quiet?'':widgetDoorScene()}</button>`;}
const widgetDecorativeIcons=[['Renewless','brand'],['Mail','mail'],['Photos','flower'],['Camera','camera'],['Clock','clock'],['Notes','notes'],['Music','music'],['Settings','settings']];
function widgetHomeScreen(){const event=widgetNearestEvent(nearestEvents(),widgetPreview.mode),date=new Date(calendarToday+'T12:00:00Z'),weekday=date.toLocaleDateString('en-US',{weekday:'long',timeZone:'UTC'}),day=date.getUTCDate();return `<div class="widget-home-preview"><div class="wk-home-date">${weekday}, ${date.toLocaleDateString('en-GB',{day:'numeric',month:'long',timeZone:'UTC'})}</div><div class="wk-small-grid"><div>${widgetTile(event,'small',{more:widgetPreview.mode==='several'?2:Math.max(0,nearestEvents().filter(r=>event&&r.renewal===event.renewal&&r.id!==event.id).length),stale:widgetPreview.mode==='stale'})}<span class="wk-app-caption">Renewless</span></div><div><button class="wk-system-calendar" data-go="Calendar" aria-label="Open calendar"><span>${weekday.toUpperCase()}</span><strong>${day}</strong><small>Your day,<br>a little clearer.</small></button><span class="wk-app-caption">Calendar</span></div></div><div class="wk-app-grid" aria-hidden="true">${widgetDecorativeIcons.map(([name,icon])=>`<div><span class="wk-app-icon wk-icon-${icon}">${icon==='brand'?'<img src="assets/renewless-mark.svg" alt="">':widgetAppGlyph(icon)}</span><small>${name}</small></div>`).join('')}</div><div class="wk-home-spacer"></div><div class="wk-page-dots" aria-hidden="true"><i></i><i></i><i></i></div><div class="wk-home-dock" aria-hidden="true">${['phone','compass','message','music'].map(icon=>`<span class="wk-app-icon wk-icon-${icon}">${widgetAppGlyph(icon)}</span>`).join('')}</div></div>`;}
function widgetAppGlyph(type){const paths={mail:'<rect x="4" y="6" width="24" height="20" rx="4"/><path d="m5 8 11 9L27 8"/>',camera:'<path d="m10 8 2-3h8l2 3h4a3 3 0 0 1 3 3v14H3V11a3 3 0 0 1 3-3Z"/><circle cx="16" cy="17" r="6"/>',clock:'<circle cx="16" cy="16" r="12"/><path d="M16 8v9l6 3"/>',notes:'<rect x="6" y="3" width="20" height="26" rx="3"/><path d="M10 10h12M10 16h12M10 22h8"/>',music:'<path d="M12 23V7l15-3v16M12 12l15-3"/><ellipse cx="8" cy="24" rx="4" ry="3"/><ellipse cx="23" cy="21" rx="4" ry="3"/>',settings:'<circle cx="16" cy="16" r="10"/><circle cx="16" cy="16" r="4"/><path d="M16 2v4m0 20v4M2 16h4m20 0h4M6 6l3 3m14 14 3 3M26 6l-3 3M9 23l-3 3"/>',flower:'<path d="M16 16C0-8 32-8 16 16c24-16 24 16 0 0 16 24-16 24 0 0-24 16-24-16 0 0Z"/>',phone:'<path d="M7 4h5l2 7-4 3q3 6 8 8l3-4 7 2v5q-1 5-7 3C10 25 3 16 3 8q0-4 4-4Z"/>',compass:'<circle cx="16" cy="16" r="12"/><path d="m22 10-4 9-8 3 4-9Z"/>',message:'<path d="M28 15q0 12-15 10l-8 4 2-8Q0 9 9 5q19-6 19 10Z"/>'};return `<svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${paths[type]||paths.clock}</svg>`;}
// Home · add widget (approved and locked 7 November 2026): one-time Home prompt when the Renewless widget is not on the Home Screen.
function widgetPromptOverlay(){const phone=[...document.querySelectorAll('.phone')].find(e=>e.offsetParent);if(!phone)return;const event=widgetNearestEvent(nearestEvents(),'next'),overlay=document.createElement('div');overlay.className='profile-dialog-overlay wk-prompt-overlay';overlay.innerHTML=`<div class="profile-dialog-shade" data-close-widget-prompt></div><section class="profile-dialog wk-prompt" role="dialog" aria-modal="true" aria-labelledby="wk-prompt-title"><header><h3 id="wk-prompt-title">Add Renewless to your Home Screen</h3><button data-close-widget-prompt aria-label="Close">×</button></header><div class="wk-prompt-preview" aria-hidden="true" inert>${widgetTile(event,'small')}</div><ul class="wk-prompt-benefits">${['See your next renewal without opening the app.','Know before a free trial turns into a charge.','Counts down to each renewal on its own.'].map(t=>`<li><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12.5 4.5 4.5L19 7.5"/></svg>${t}</li>`).join('')}</ul><ol class="wk-prompt-steps"><li>Touch and hold an empty area of your Home Screen.</li><li>Tap <b>+</b>, then search for Renewless.</li><li>Choose the widget and tap <b>Add Widget</b>.</li></ol><button type="button" class="wk-prompt-watch" data-widget-video><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="m10 8.5 5.5 3.5-5.5 3.5Z"/></svg>Watch how to add it</button><div class="profile-dialog-actions"><button type="button" class="secondary" data-close-widget-prompt>Not now</button><button type="button" class="primary" data-close-widget-prompt>Got it</button></div></section>`;phone.append(overlay);}
function widgetVideoSheet(){const phone=[...document.querySelectorAll('.phone')].find(e=>e.offsetParent);if(!phone)return;const event=widgetNearestEvent(nearestEvents(),'next'),apps=['mail','flower','camera','clock','notes','music','settings','compass'],sheet=document.createElement('div');sheet.className='profile-dialog-overlay wk-video-overlay';sheet.innerHTML=`<div class="profile-dialog-shade" data-close-widget-video></div><section class="profile-dialog wk-video" role="dialog" aria-modal="true" aria-labelledby="wk-video-title"><header><h3 id="wk-video-title">How to add the widget</h3><button data-close-widget-video aria-label="Close video">×</button></header><div class="wk-video-frame" role="img" aria-label="Short video: touch and hold the Home Screen, tap plus, search Renewless and tap Add Widget."><div class="wk-video-screen"><div class="wk-video-plus">+</div><div class="wk-video-grid">${apps.map(a=>`<span class="wk-app-icon wk-icon-${a}">${widgetAppGlyph(a)}</span>`).join('')}</div><span class="wk-video-touch"></span><div class="wk-video-gallery"><b>Search Widgets</b><span><img src="assets/renewless-mark.svg" alt="">Renewless</span><i>Add Widget</i></div><div class="wk-video-drop">${widgetTile(event,'small')}</div></div><div class="wk-video-caption"><span>1 · Touch and hold</span><span>2 · Tap +</span><span>3 · Search Renewless</span><span>4 · Add Widget</span></div></div><div class="wk-video-bar"><span></span></div><p class="wk-video-note">0:12 · Replays automatically</p><button type="button" class="primary" data-close-widget-video>Done</button></section>`;phone.append(sheet);}
document.addEventListener('click',e=>{if(e.target.closest('[data-widget-video]'))widgetVideoSheet();else if(e.target.closest('[data-close-widget-video]'))document.querySelector('.wk-video-overlay')?.remove();else if(e.target.closest('[data-close-widget-prompt]'))document.querySelector('.wk-prompt-overlay')?.remove();});
function widgetPreviewAfterRender(){document.getElementById('widget-preview-controls')?.remove();if(current==='Home · add widget')widgetPromptOverlay();if(current!=='Widgets')return;document.getElementById('context').textContent='Final Widgets · approved and locked Small widget with +N and Needs update,, event/trial/quiet states and knock motion. Fictional wallpaper/calendar; subscription snapshots follow the shared schedule. Browser motion is a concept, not a native widget installation.';document.querySelector('[data-variant=upgraded] .variant-title h2').textContent='Final';document.querySelector('[data-variant=upgraded] .variant-title small').textContent='Final design · locked';document.querySelector('.footnote').innerHTML='Preview the short knock → reveal, then tap a Renewless widget to open its subscription. iPhone widgets animate supported data updates for up to 2 seconds; no continuous loop or guaranteed animation whenever Home Screen opens. <a href="https://developer.apple.com/documentation/widgetkit/animating-data-updates-in-widgets-and-live-activities" target="_blank" rel="noopener noreferrer">Apple WidgetKit guidance</a>.';document.getElementById('context').insertAdjacentHTML('afterend',`<div class="widget-preview-controls" id="widget-preview-controls" aria-label="Widget inspection controls"><span>PREVIEW</span>${[['next','Next event'],['trial','Trial ending'],['several','Several due'],['quiet','All clear'],['stale','Needs update']].map(([mode,label])=>`<button data-widget-mode="${mode}" aria-pressed="${widgetPreview.mode===mode}">${label}</button>`).join('')}<button data-widget-replay>↻ Replay knock</button></div>`);}
document.addEventListener('click',e=>{const mode=e.target.closest('[data-widget-mode]'),replay=e.target.closest('[data-widget-replay]'),tile=e.target.closest('[data-widget-open]');if(mode){widgetPreview.mode=mode.dataset.widgetMode;render();}else if(replay){render();}else if(tile){const record=allTrackedRecords().find(r=>r.id===tile.dataset.widgetOpen);if(record)openCalendarRecord(record);else go('Home');}});
